export const getPageByPath = (path) => siteContent.pages.find((page) => page.path === path || page.legacyPath === path);

export const getPathForSlug = (slug) => siteContent.routes.find((route) => route.slug === slug)?.path || `/${slug.removesuffix('.php')}`;

export default siteContent;
